"""news-image-20261117 entry.

Writes the front page "THE WORLD TODAY, Tuesday 17 November 2026"
to the output directory as entry.png.

The image is embedded below as a base64 literal and written out
byte for byte. Standard library only, no network, deterministic:
every run writes the same bytes. The output file keeps the name
entry.png even though the bytes are a JPEG, as the rules allow.
"""

import base64
import os
import sys

# The front page image, base64-encoded JPEG bytes.
_IMAGE_B64 = ""


def main() -> int:
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "out")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(_IMAGE_B64)
    out_path = os.path.join(out_dir, "entry.png")
    with open(out_path, "wb") as f:
        f.write(data)
    return 0


if __name__ == "__main__":
    sys.exit(main())
